using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using NightTales.Domain.Usage;

namespace NightTales.Infrastructure.Persistence.Configurations;

/// <summary>
/// The <c>price_versions</c> table (02 README D14, CR-2): immutable, append-only versioned rates and
/// limits. <c>version</c> is assigned by the seeder as <c>max + 1</c>, so it is never generated by the
/// database; <c>rates</c> and <c>limits</c> are jsonb documents kept as text in the model, like
/// <c>generation_runs.models</c>.
/// </summary>
internal sealed class PriceVersionConfiguration : IEntityTypeConfiguration<PriceVersion>
{
    public void Configure(EntityTypeBuilder<PriceVersion> builder)
    {
        builder.ToTable("price_versions");
        builder.HasKey(version => version.Version);
        builder.Property(version => version.Version).ValueGeneratedNever();

        builder.Property(version => version.ActiveFrom).IsRequired();
        builder.Property(version => version.Rates).HasColumnType("jsonb").IsRequired();
        builder.Property(version => version.Limits).HasColumnType("jsonb").IsRequired();
        builder.Property(version => version.ConfigHash).IsRequired();

        // The seeder's idempotence key: one row per distinct config.
        builder.HasIndex(version => version.ConfigHash).IsUnique();

        // IPriceCatalog.GetActive: newest active_from <= queued_at.
        builder.HasIndex(version => version.ActiveFrom).IsDescending(true);
    }
}
